diff --git a/src/bookings/strategies/optimistic.strategy.ts b/src/bookings/strategies/optimistic.strategy.ts
new file mode 100644
--- /dev/null
+++ b/src/bookings/strategies/optimistic.strategy.ts
@@ -0,0 +1,60 @@
+import { Injectable } from '@nestjs/common';
+import { NoCapacityError, RetryExhaustedError } from '../../common/errors';
+import { PrismaService } from '../../prisma/prisma.service';
+import {
+  countOverlapping,
+  insertHeld,
+  jitter,
+  type ReservedBooking,
+  type ReserveInput,
+  type ReserveStrategy,
+  sleep,
+} from './reserve.strategy';
+
+class VersionConflict extends Error {}
+
+/**
+ * No locks: count, insert, then bump the resource's version guarded by the version we read.
+ * A competing transaction that committed first makes the guarded update touch 0 rows; we roll
+ * back and try again, and the retry's count sees the winner's booking.
+ */
+@Injectable()
+export class OptimisticStrategy implements ReserveStrategy {
+  readonly name = 'optimistic' as const;
+  static readonly MAX_ATTEMPTS = 6;
+  attempts = 0;
+  retries = 0;
+
+  constructor(private readonly prisma: PrismaService) {}
+
+  async reserve(input: ReserveInput): Promise<ReservedBooking> {
+    for (let attempt = 0; ; attempt += 1) {
+      this.attempts += 1;
+      try {
+        return await this.prisma.$transaction(async (tx) => {
+          const seen = await tx.resource.findUniqueOrThrow({
+            where: { id: input.resource.id },
+            select: { version: true },
+          });
+          if ((await countOverlapping(tx, input)) >= input.resource.capacity) {
+            throw new NoCapacityError(input.resource.id);
+          }
+          const booking = await insertHeld(tx, input);
+          const bumped = await tx.resource.updateMany({
+            where: { id: input.resource.id, version: seen.version },
+            data: { version: { increment: 1 } },
+          });
+          if (bumped.count === 0) throw new VersionConflict();
+          return booking;
+        });
+      } catch (error) {
+        if (!(error instanceof VersionConflict)) throw error;
+        if (attempt + 1 >= OptimisticStrategy.MAX_ATTEMPTS) {
+          throw new RetryExhaustedError(this.name, OptimisticStrategy.MAX_ATTEMPTS);
+        }
+        this.retries += 1;
+        await sleep(jitter(attempt));
+      }
+    }
+  }
+}
diff --git a/src/bookings/strategies/reserve.strategy.ts b/src/bookings/strategies/reserve.strategy.ts
new file mode 100644
--- /dev/null
+++ b/src/bookings/strategies/reserve.strategy.ts
@@ -0,0 +1,80 @@
+import type { Strategy } from '../../config';
+import type { PrismaService } from '../../prisma/prisma.service';
+
+export interface ReserveInput {
+  resource: { id: string; capacity: number; exclusive: boolean };
+  userId: string;
+  startsAt: Date;
+  endsAt: Date;
+  holdExpiresAt: Date;
+}
+
+export interface ReservedBooking {
+  id: string;
+  resourceId: string;
+  userId: string;
+  startsAt: Date;
+  endsAt: Date;
+  status: 'HELD';
+  holdExpiresAt: Date | null;
+}
+
+/**
+ * Creates a HELD booking if the resource has capacity for [startsAt, endsAt), atomically with
+ * respect to every other caller — or throws NoCapacityError. Each implementation serialises
+ * differently; see docs/adr/0001.
+ */
+export interface ReserveStrategy {
+  readonly name: Strategy;
+  reserve(input: ReserveInput): Promise<ReservedBooking>;
+}
+
+export const RESERVE_STRATEGY = Symbol('RESERVE_STRATEGY');
+
+/** The transaction client Prisma hands to `$transaction(async (tx) => …)`. */
+export type Tx = Parameters<Parameters<PrismaService['$transaction']>[0]>[0];
+
+export const ACTIVE = ['HELD', 'CONFIRMED'] as const;
+
+/** Active bookings of the resource that intersect the slot (half-open intervals). */
+export function countOverlapping(tx: Tx, input: ReserveInput): Promise<number> {
+  return tx.booking.count({
+    where: {
+      resourceId: input.resource.id,
+      status: { in: [...ACTIVE] },
+      startsAt: { lt: input.endsAt },
+      endsAt: { gt: input.startsAt },
+    },
+  });
+}
+
+export function insertHeld(tx: Tx, input: ReserveInput): Promise<ReservedBooking> {
+  return tx.booking.create({
+    data: {
+      resourceId: input.resource.id,
+      userId: input.userId,
+      startsAt: input.startsAt,
+      endsAt: input.endsAt,
+      exclusive: input.resource.exclusive,
+      status: 'HELD',
+      holdExpiresAt: input.holdExpiresAt,
+    },
+    select: {
+      id: true,
+      resourceId: true,
+      userId: true,
+      startsAt: true,
+      endsAt: true,
+      status: true,
+      holdExpiresAt: true,
+    },
+  }) as Promise<ReservedBooking>;
+}
+
+export function sleep(ms: number): Promise<void> {
+  return new Promise((resolve) => setTimeout(resolve, ms));
+}
+
+export function jitter(attempt: number): number {
+  return Math.floor(Math.random() * 20 * 2 ** attempt);
+}
diff --git a/src/bookings/strategies/serializable.strategy.ts b/src/bookings/strategies/serializable.strategy.ts
new file mode 100644
--- /dev/null
+++ b/src/bookings/strategies/serializable.strategy.ts
@@ -0,0 +1,51 @@
+import { Injectable } from '@nestjs/common';
+import { isRetryableConflict, NoCapacityError, RetryExhaustedError } from '../../common/errors';
+import { PrismaService } from '../../prisma/prisma.service';
+import {
+  countOverlapping,
+  insertHeld,
+  jitter,
+  type ReservedBooking,
+  type ReserveInput,
+  type ReserveStrategy,
+  sleep,
+} from './reserve.strategy';
+
+/**
+ * The textbook answer: the same count-then-insert in a SERIALIZABLE transaction. Postgres tracks
+ * the predicate the count read; a concurrent insert into it fails one of the transactions at
+ * commit with 40001, and that one is retried.
+ */
+@Injectable()
+export class SerializableStrategy implements ReserveStrategy {
+  readonly name = 'serializable' as const;
+  static readonly MAX_ATTEMPTS = 8;
+  attempts = 0;
+  retries = 0;
+
+  constructor(private readonly prisma: PrismaService) {}
+
+  async reserve(input: ReserveInput): Promise<ReservedBooking> {
+    for (let attempt = 0; ; attempt += 1) {
+      this.attempts += 1;
+      try {
+        return await this.prisma.$transaction(
+          async (tx) => {
+            if ((await countOverlapping(tx, input)) >= input.resource.capacity) {
+              throw new NoCapacityError(input.resource.id);
+            }
+            return insertHeld(tx, input);
+          },
+          { isolationLevel: 'Serializable' },
+        );
+      } catch (error) {
+        if (!isRetryableConflict(error)) throw error;
+        if (attempt + 1 >= SerializableStrategy.MAX_ATTEMPTS) {
+          throw new RetryExhaustedError(this.name, SerializableStrategy.MAX_ATTEMPTS);
+        }
+        this.retries += 1;
+        await sleep(jitter(attempt));
+      }
+    }
+  }
+}
